-- A person's name is unique on its sheet, ignoring case and surrounding spaces.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(name));
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
-- A person may have aliases, each stored without surrounding spaces. An alias is unique on its sheet, ignoring case,
-- as names are; the store keeps an alias from equalling a name.
CREATE TABLE person_alias (
    person_id BIGINT NOT NULL REFERENCES person (id),
    sheet_id VARCHAR(100) NOT NULL,
    alias VARCHAR(200) NOT NULL,
    alias_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(alias))
);
CREATE UNIQUE INDEX person_alias_sheet_alias ON person_alias (sheet_id, alias_key);
-- A person may have a contact, stored without surrounding spaces and lower-cased, unique on its sheet. Null: none.
ALTER TABLE person ADD COLUMN contact VARCHAR(200);
CREATE UNIQUE INDEX person_sheet_contact ON person (sheet_id, contact);

